Self-Service Portal Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Self-Service Portal Container container

Container_Boundary(self_service_portal_container, "Self-Service Portal Container") {
    Component(CatalogSearchComponent, "Catalog Search Component", "Kubernetes, Envoy", "Provides high-performance catalog search capabilities with sub-800ms response times under heavy loads.")
    Component(CirculationManagementComponent, "Circulation Management Component", "Kubernetes", "Manages book lending, returns, and library patron account operations.")
    Component(SelfServicePortalFrontend, "Self-Service Portal Frontend", "HTTPS (TLS 1.3)", "Provides the web interface for library patrons to access cataloging and circulation features.")
}

Rel(SelfServicePortalFrontend, CatalogSearchComponent, "Executes catalog searches", "Internal API")
Rel(SelfServicePortalFrontend, CirculationManagementComponent, "Manages checkouts and accounts", "Internal API")
@enduml

Notification Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Notification Container container

Container_Boundary(notification_container, "Notification Container") {
    Component(Notification_Dispatcher, "Notification Dispatcher", "Kubernetes / Asynchronous Consumer", "Asynchronously consumes messages, handles backpressure, and dispatches alerts to external providers.")
    Component(Preference_Manager, "Preference Manager", "Internal Preference Database / AES-256", "Manages multi-channel patron and staff preferences with EU-restricted, encrypted storage.")
    Component(Retry_and_DLQ_Handler, "Retry and DLQ Handler", "Apache Kafka / AWS SQS", "Manages retries and dead-letter queues to prevent cascading failures during dispatches.")
}

Rel(Notification_Dispatcher, Preference_Manager, "Queries multi-channel notification preferences", "Internal secure access")
Rel(Notification_Dispatcher, Retry_and_DLQ_Handler, "Routes failed deliveries for retry or dead-letter processing", "Kafka/SQS")

@enduml

Analytics/Reporting Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Analytics/Reporting Container container

Container_Boundary("Analytics/Reporting Container", "Analytics/Reporting Container") {
    Component("ETL Pipeline Engine", "ETL Pipeline Engine", "Apache Spark, dbt", "Executes scheduled off-peak ETL pipelines, data transformations, and pseudonymization for compliance audits.")
    Component("Reporting API Controller", "Reporting API Controller", "Kubernetes, OAuth2/OIDC", "Provides secure, anonymized data access and enforces Role-Based Access Control and Dynamic Row-Level Security.")
    Component("Export Generation Worker", "Export Generation Worker", "Apache Kafka / AWS SQS", "Decouples asynchronous export generation and message queuing for circulation insights.")
}

Rel("Reporting API Controller", "ETL Pipeline Engine", "Queries analytical data asynchronously", "")
Rel("Export Generation Worker", "Reporting API Controller", "Processes queued export tasks", "")

@enduml
